insert into question_bank_items (id, stage_id, position, question, hint, answer) values (52, 4, 6, 'What is Infrastructure as Code, and how do you test it?', 'If infra is code, it gets reviewed, linted and tested like code.', ARRAY['IaC (Terraform, CloudFormation, Pulumi) declares infrastructure in version-controlled files, so environments are reproducible and changes are reviewable instead of clicked in a console.', 'Test it in layers: static analysis and linting, policy checks (tfsec, OPA) for security and cost, a `plan`/dry-run diff on every PR, and integration tests that apply to a throwaway environment and assert the resources actually work.', 'The payoff is the same one that makes tests valuable — reproducibility and no hidden manual drift — so a validated `plan` becomes a gate, just like a green test run.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (53, 4, 7, 'How do you get an ephemeral or preview environment per pull request?', 'Spin it up on open, tear it down on merge — isolated and disposable.', ARRAY['On PR open, the pipeline provisions an isolated stack — often containers via compose or a namespace via IaC — seeds data, deploys the branch, and posts the URL back on the PR.', 'It gives reviewers and e2e tests a real, isolated target with no shared-state collisions, and it is destroyed on merge or close so nothing lingers or costs money.', 'The prerequisites are the same as reproducible builds: everything as code, seedable data, and no manual setup — which is exactly what makes the environment trustworthy to test against.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (54, 4, 8, 'What is a post-deploy smoke test, and what should it check?', 'A tiny, fast set that proves the deploy is alive — not full regression.', ARRAY['A handful of critical, fast checks run right after a deploy: the app is up, health endpoint green, login works, the money path responds, and dependencies (DB, key services) are reachable.', 'It must be fast and rock-solid, because it gates the release and, in a canary or blue-green flow, decides whether to widen or roll back.', 'Keep it shallow on purpose — it answers "is this deploy fundamentally broken?", not "is everything correct?" The full regression runs earlier in the pipeline.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (55, 4, 9, 'How do you keep environments in parity (dev, staging, prod)?', 'Drift between environments is where "works on staging" bugs come from.', ARRAY['Build every environment from the same IaC and container images, with config injected per environment rather than baked in — so they differ only in scale and secrets, not in shape.', 'Keep versions, schemas and dependencies aligned, and refresh staging data (anonymised) so it resembles production. Drift is the root of bugs that only appear after release.', 'Accept the honest limits — production has real data volume, traffic and third parties you cannot fully mirror — and cover that gap with canary releases and production monitoring.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (56, 4, 10, 'What are feature flags, and how do they change your testing strategy?', 'Deploy is no longer release; the flag combination is now under test.', ARRAY['A feature flag gates code at runtime, so you can deploy dark and release by toggling — decoupling deployment from release and enabling canary and instant kill-switches.', 'They multiply the state space: you now test the flag on, off, and the risky combinations, and you make sure the off state is truly inert. Test the default a new user gets, too.', 'Operationally, keep flags short-lived — stale flags rot into untested dead branches — and have QA verify the flag can be turned off cleanly under load, since that is your rollback.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (57, 4, 11, 'How do you test database migrations safely?', 'Migrations are one-way and touch live data — treat them as high-risk.', ARRAY['Test the migration forward and its rollback on a copy of production-shaped data, and assert data integrity and row counts before and after — not just that it ran.', 'Prefer expand-then-contract: add the new column/table, backfill and dual-write, switch reads, and only then drop the old — so the app stays compatible with both schemas and a rollback is possible.', 'Rehearse on staging with realistic volume to catch a lock or a slow backfill that would take the site down, and never make a destructive change in the same release that starts using it.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (58, 4, 12, 'How do you roll back a bad release, and how do you test the rollback?', 'A rollback you have never tested is a hope, not a plan.', ARRAY['Prefer a fast, clean mechanism — flip blue-green, redeploy the previous immutable image, or turn off a feature flag — over a frantic hotfix.', 'The hard part is data: a schema or data change may not reverse, which is why expand-then-contract migrations and backward-compatible changes keep rollback on the table.', 'Rehearse it: practise the rollback in staging, time it, and add a post-rollback smoke test so you can prove the previous version is healthy, not just deployed.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (59, 4, 13, 'What is observability, and how does it help testing?', 'Logs, metrics and traces — so a failure explains itself.', ARRAY['Observability is the ability to ask new questions about a running system from its outputs — structured logs, metrics and distributed traces — without shipping new code to investigate.', 'For testing it turns a vague "it failed" into a replayable story: a trace shows which service and call broke, metrics show whether it is a trend or a blip, and logs give the detail.', 'It also enables testing in production — canary analysis, synthetic monitoring, alerting on SLOs — which catches the issues no pre-prod environment can reproduce.']::text[]);